const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const root = process.cwd();
const dependencyRoot = process.env.SYNAPSE_DEPENDENCY_ROOT;
if (!dependencyRoot) {
  console.error('PREREQUISITE_MISSING: SYNAPSE_DEPENDENCY_ROOT is not set');
  process.exit(127);
}
const dependencyModules = path.join(dependencyRoot, 'node_modules');
const nextBin = path.join(dependencyModules, 'next', 'dist', 'bin', 'next');
const nextPackage = path.join(dependencyModules, 'next', 'package.json');
if (!fs.existsSync(nextBin) || !fs.existsSync(nextPackage)) {
  console.error('PREREQUISITE_MISSING: install the exact package.json dependencies before verification; no network is used by this driver');
  process.exit(127);
}
const installed = JSON.parse(fs.readFileSync(nextPackage, 'utf8')).version;
if (installed !== '15.5.9') {
  console.error(`PREREQUISITE_VERSION_MISMATCH: expected next 15.5.9, got ${installed}`);
  process.exit(126);
}
const result = spawnSync(process.execPath, [nextBin, 'build'], {
  cwd: root,
  encoding: 'utf8',
  env: { ...process.env, CI: '1', FORCE_COLOR: '0', NEXT_TELEMETRY_DISABLED: '1', NO_COLOR: '1' }
});
if (result.error) {
  console.error(`DRIVER_EXEC_ERROR: ${result.error.message}`);
  process.exit(125);
}
process.stderr.write(`${result.stdout || ''}${result.stderr || ''}`);
process.exit(result.status === null ? 125 : result.status);

